     <main id="maincontent" class="page-shell" tabindex="-1">
       <div id="app"></div>
     </main>

     <script>
       const quizData = [
         {
           id: "q1",
           prompt: "Which of these are programming languages?",
           help: "Choose all that apply.",
           options: [
             { id: "q1-py", label: "Python" },
             { id: "q1-html", label: "HTML" },
             { id: "q1-js", label: "JavaScript" },
             { id: "q1-css", label: "CSS" }
           ]
         },
         {
           id: "q2",
           prompt: "Which languages are commonly used for system programming?",
           options: [
             { id: "q2-c", label: "C" },
             { id: "q2-rust", label: "Rust" },
             { id: "q2-ruby", label: "Ruby" },
             { id: "q2-go", label: "Go" }
           ]
         },
         {
           id: "q3",
           prompt: "Which of these are JavaScript runtimes or related platforms?",
           options: [
             { id: "q3-node", label: "Node.js" },
             { id: "q3-deno", label: "Deno" },
             { id: "q3-php", label: "PHP" },
             { id: "q3-bun", label: "Bun" }
           ]
         }
       ];

       const app = document.getElementById("app");

       function QuestionField(question) {
         const helpId = question.help ? `${question.id}-help` : "";
         const optionMarkup = question.options
           .map(
             (option) => `
               <label class="option" for="${option.id}">
                 <input id="${option.id}" name="${question.id}" type="checkbox" value="${option.label}" />
                 <span>
                   <span class="option-label">${option.label}</span>
                 </span>
               </label>
             `
           )
           .join("");

         return `
           <div class="form-field">
             <fieldset ${helpId ? `aria-describedby="${helpId}"` : ""}>
               <legend>${question.prompt}</legend>
               ${question.help ? `<p class="help-text" id="${helpId}">${question.help}</p>` : ""}
               <div class="options">
                 ${optionMarkup}
               </div>
             </fieldset>
           </div>
         `;
       }

       function QuizApp() {
         return `
           <section aria-labelledby="quiz-title">
             <header class="hero">
               <span class="eyebrow">Interactive quiz</span>
               <h1 id="quiz-title">Computer languages quiz</h1>
               <p class="subtitle">Select every answer that fits each question, then submit to see how many choices you picked.</p>
             </header>

             <div class="quiz-card">
               <form id="quiz-form" novalidate>
                 ${quizData.map(QuestionField).join("")}
                 <div class="actions">
                   <button class="submit-button" type="submit">Submit quiz</button>
                   <p class="status" id="quiz-status" aria-live="polite">Ready when you are.</p>
                 </div>
               </form>
             </div>
           </section>
         `;
       }

       app.innerHTML = QuizApp();

       const form = document.getElementById("quiz-form");
       const status = document.getElementById("quiz-status");

       form.addEventListener("submit", (event) => {
         event.preventDefault();

         const totalSelected = quizData.reduce((count, question) => {
           return (
             count +
             Array.from(form.elements[question.id] || []).filter((control) => control.checked).length
           );
         }, 0);

         status.textContent = `Submitted. You selected ${totalSelected} answer${totalSelected === 1 ? "" : "s"}.`;
         status.dataset.state = "success";
       });
     </script>
   </body>
 </html>

